-- ============================================================
-- 0080_rondas_matematicas_nuevo_banco.sql
-- GENERADO por scripts/build-rondas.mjs — no editar a mano.
--
-- Matemáticas cambia de banco de preguntas: el documento del equipo
-- académico de 50 preguntas (tipo Saber) reemplaza al de 20. Los módulos 4
-- (primera ronda) y 6 (ronda final) cambian sus preguntas por:
--   primera ronda: mate-01, mate-02, mate-03, mate-04, mate-05, mate-06, mate-07, mate-08, mate-14, mate-15
--   ronda final:   mate-09, mate-10, mate-11, mate-12, mate-13, mate-16, mate-17, mate-18, mate-19, mate-20
-- (en la ronda va la 4–6 completa en la primera y la 9–13 completa en la
-- final: comparten información y no se parten).
--
-- Qué toca, en la familia COMPLETA del curso (base, copias por colegio y
-- copias de copias):
--   - Ronda cuyas preguntas vienen TODAS del banco anterior (ids "mat-NN",
--     sean las predeterminadas o elegidas por el tutor) → REEMPLAZADA.
--     Solo cambia challenge_data.questions: título, orden, XP, progreso de
--     los estudiantes y la guía del bloque se conservan.
--   - Ronda con preguntas propias del tutor → NO TOCADO (se informa).
--   - Ronda que ya tiene el banco nuevo ("mate-NN") → YA APLICADA.
-- Los ids nuevos son distintos a propósito: el análisis de ítems agrupa por
-- id y no debe mezclar respuestas de preguntas diferentes.
-- Además, la clase en vivo pasa a llevar las imágenes de las OPCIONES
-- (optionImages): las preguntas 12, 33, 42 y 43 tienen gráficas o tablas
-- como opciones de respuesta.
-- Requiere 0075. Idempotente. EJECUTAR en Supabase SQL Editor.
-- ============================================================

-- ── 1. Snapshot de la clase en vivo con imágenes por opción ────────────
-- Igual que en 0075 + 'optionImages'. La respuesta correcta sigue SOLO en
-- live_session_keys.
create or replace function public._snapshot_module_questions(p_module_id uuid, p_default_time int default 20)
returns jsonb
language plpgsql set search_path = public as $$
declare
  v_questions jsonb;
  v_snapshot  jsonb := '[]'::jsonb;
  v_keys      jsonb := '[]'::jsonb;
  q jsonb;
begin
  select challenge_data->'questions' into v_questions from public.course_modules where id = p_module_id;

  for q in select value from jsonb_array_elements(coalesce(v_questions, '[]'::jsonb)) as t(value) loop
    v_snapshot := v_snapshot || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'question',      q->>'question',
      'questionAfter', q->>'questionAfter',
      'options',       coalesce(q->'options', '[]'::jsonb),
      'optionImages',  q->'optionImages',
      'image',         q->>'image',
      'imageHeight',   q->'imageHeight',
      'passage',       q->'passage',
      'hint',          q->>'hint',
      'time_limit_s',  coalesce(nullif(q->>'timeLimit','')::int, p_default_time)
    )));
    v_keys := v_keys || jsonb_build_array(jsonb_build_object(
      'correct',          (q->>'correct')::int,
      'points',           coalesce(nullif(q->>'points','')::int, 1000),
      'time_limit_s',     coalesce(nullif(q->>'timeLimit','')::int, p_default_time),
      'explanation',      q->>'explanation',
      'explanationImage', q->>'explanationImage'
    ));
  end loop;

  return jsonb_build_object('snapshot', v_snapshot, 'keys', v_keys);
end; $$;
revoke execute on function public._snapshot_module_questions(uuid, int) from public;

-- ── 2. Preguntas nuevas en las rondas ───────────────────────────────────
drop table if exists _0080_estado;
create temp table _0080_estado (estado text, curso text, detalle text);

do $$
declare
  v_base uuid := (select coalesce(parent_course_id, id) from public.courses where id = '88136e1a-4564-45bd-b514-0ad6690b182c'::uuid);
  v_r1 jsonb := $mat1${"bank":"matematicas","bankRound":1,"passingScore":0,"questions":[{"id":"mate-01","question":"Cuatro cursos, cada uno con igual número de estudiantes, presentan anualmente una prueba de matemáticas. La tabla muestra el puntaje promedio obtenido por cada curso.\nAl revisar los puntajes de la tabla, una persona afirma que hubo un aumento en el puntaje respecto al año anterior. Esta afirmación es","options":["Correcta, ya que el promedio de la mayoría de los cursos aumentó respecto al año anterior.","Incorrecta, ya que el promedio total en el año anterior es superior al promedio total en el año actual.","Correcta, ya que al observar todos los promedios, el mayor corresponde al curso I en el año actual.","Incorrecta, ya que se necesita el puntaje de cada estudiante para realizar la comparación."],"correct":1,"hint":"Como todos los cursos tienen el mismo número de estudiantes, compara la SUMA de los promedios de cada año.","difficulty":"dificil","timeLimit":120,"image":"/preguntas/matematicas/promedios-cursos.jpg","explanation":"Con cursos del mismo tamaño, el promedio total de cada año se compara sumando los promedios: año anterior 63 + 61 + 50 + 53 = 227; año actual 65 + 45 + 53 + 54 = 217. El promedio total bajó, aunque tres de los cuatro cursos subieron: la caída del curso II (16 puntos) pesa más que esas subidas."},{"id":"mate-02","question":"Una persona que vive en Colombia tiene inversiones en dólares en Estados Unidos, y sabe que la tasa de cambio del dólar respecto al peso colombiano se mantendrá constante este mes, siendo 1 dólar equivalente a 4.000 pesos colombianos y que su inversión, en dólares, le dará ganancias del 3 % en el mismo periodo. Un amigo le asegura que en pesos sus ganancias también serán del 3 %.\n¿La afirmación de su amigo es correcta?","options":["Sí, porque, sin importar las variaciones en la tasa de cambio, la proporción en que aumenta la inversión en dólares es la misma que en pesos.","No, porque debería conocerse el valor exacto de la inversión para poder calcular la cantidad de dinero que ganará.","Sí, porque el 3 % representa una proporción fija en cualquiera de las dos monedas, puesto que la tasa de cambio permanecerá constante.","No, porque el 3 % representa un incremento, que será mayor en pesos colombianos, pues en esta moneda cada dólar representa un valor 4.000 veces mayor."],"correct":2,"hint":"Si la tasa de cambio no se mueve, ¿pasar la inversión a pesos cambia el porcentaje de ganancia?","difficulty":"media","timeLimit":120,"explanation":"Pasar de dólares a pesos es multiplicar por 4.000 tanto la inversión como la ganancia. Como la tasa es constante, la proporción entre ganancia e inversión no cambia: en pesos también es del 3 %. A es incorrecta porque la conclusión depende justamente de que la tasa no varíe."},{"id":"mate-03","question":"Las directivas de un colegio tienen que organizar un viaje a un museo con 140 estudiantes, quienes deben dividirse en 3 grupos. Cada grupo irá en una franja diferente, pero el costo total de las entradas se asumirá equitativamente por los estudiantes. En la tabla se muestran los horarios disponibles, la máxima cantidad de estudiantes y los precios respectivos de cada horario.\nCon el fin de que todos los estudiantes asistan y paguen el menor precio, las directivas eligieron las franjas 1, 3 y 4. ¿Esta elección garantiza que asistan todos los estudiantes al menor precio posible?","options":["Sí, porque esas franjas suman exactamente 140 estudiantes.","No, porque es posible obtener un precio menor eligiendo la franja 2 en lugar de la franja 3.","Sí, porque se incluyó la franja 1 que es la de menor precio por estudiante.","No, porque en la franja 3 la cantidad máxima de estudiantes es 30."],"correct":1,"hint":"Las franjas no tienen que llenarse por completo: ¿qué pasa si cambias la franja más cara por otra?","difficulty":"media","timeLimit":135,"image":"/preguntas/matematicas/franjas-museo.jpg","explanation":"Con las franjas 1, 3 y 4: 50 × 35.000 + 30 × 50.000 + 60 × 45.000 = $ 5.950.000. Con las franjas 1, 2 y 4 (caben 150) se llenan primero las más baratas: 50 × 35.000 + 40 × 40.000 + 50 × 45.000 = $ 5.600.000, que es menos. La franja 3 es la más cara por estudiante."},{"id":"mate-04","question":"La empresa pagará $4.200.000 por capacitar a los trabajadores de la dependencia “Insumos” en el módulo I, ¿cuántos empleados tiene esta dependencia?","options":["Entre 20 y 30 trabajadores.","Entre 41 y 60 trabajadores.","Entre 61 y 90 trabajadores.","Entre 80 y 120 trabajadores."],"correct":2,"hint":"Calcula cuánto cuesta un curso del módulo I y cuántos cursos se pagan con $ 4.200.000.","difficulty":"facil","timeLimit":105,"explanation":"Un curso del módulo I cuesta 40 h × $ 35.000 = $ 1.400.000. Con $ 4.200.000 se pagan 3 cursos, cada uno de 20 a 30 personas: la dependencia tiene entre 60 y 90 trabajadores.","passage":{"intro":"Lee la siguiente información para responder.","title":"Capacitación en informática básica","paragraphs":["Para capacitar en informática básica a los trabajadores de algunas dependencias de una empresa, se contrata una institución que ofrece un plan educativo de 4 módulos (ver Tabla)."],"images":[{"url":"/preguntas/matematicas/capacitacion-informatica.jpg"}]}},{"id":"mate-05","question":"Si se les cobrara a los 50 trabajadores de la dependencia “Recursos Humanos” la capacitación del módulo II, y todos pagaran el mismo valor, ¿cuánto debería pagar cada uno por esa capacitación?","options":["$ 18.000","$ 36.000","$ 450.000","$ 900.000"],"correct":1,"hint":"50 personas no caben en un solo curso: ¿cuántos cursos se necesitan y cuánto vale cada uno?","difficulty":"facil","timeLimit":105,"explanation":"Un curso del módulo II cuesta 30 h × $ 30.000 = $ 900.000. Como cada curso admite máximo 30 personas, los 50 trabajadores necesitan 2 cursos: $ 1.800.000, que entre 50 da $ 36.000 por persona.","passage":{"intro":"Lee la siguiente información para responder.","title":"Capacitación en informática básica","paragraphs":["Para capacitar en informática básica a los trabajadores de algunas dependencias de una empresa, se contrata una institución que ofrece un plan educativo de 4 módulos (ver Tabla)."],"images":[{"url":"/preguntas/matematicas/capacitacion-informatica.jpg"}]}},{"id":"mate-06","question":"La empresa paga $ 900.000 por la capacitación de los 40 funcionarios de la dependencia “Importaciones”. De acuerdo con el valor pagado, ¿cuál de los siguientes módulos corresponde al tomado por la dependencia \"Importaciones\"?","options":["I.","II.","III.","IV."],"correct":3,"hint":"40 funcionarios necesitan 2 cursos. ¿Cuánto costó entonces cada curso?","difficulty":"dificil","timeLimit":105,"explanation":"Con máximo 30 personas por curso, 40 funcionarios necesitan 2 cursos: cada uno costó $ 900.000 ÷ 2 = $ 450.000. Solo el módulo IV cuesta eso: 10 h × $ 45.000. (Un curso del módulo II cuesta $ 900.000, pero habría que pagar dos.)","passage":{"intro":"Lee la siguiente información para responder.","title":"Capacitación en informática básica","paragraphs":["Para capacitar en informática básica a los trabajadores de algunas dependencias de una empresa, se contrata una institución que ofrece un plan educativo de 4 módulos (ver Tabla)."],"images":[{"url":"/preguntas/matematicas/capacitacion-informatica.jpg"}]}},{"id":"mate-07","question":"La figura muestra el portalápices de Eliécer. Él sabe que es posible colocar un caucho de 18 cm de perímetro alrededor de la base sin estirarlo, pero a medida que sube el caucho por el portalápices, este se estira hasta que, en la boca del portalápices, su perímetro es 24 cm.\nEl portalápices tiene base y boca cuadrada, por lo cual Eliécer afirma: “Como los perímetros de la base y la boca del portalápices están en relación 18/24=3/4, el área de la base debe ser también tres cuartas partes del área de la boca del portalápices”. ¿Es verdadera esta afirmación?","options":["No, porque la medición se realiza con el mismo caucho y, por tanto, las áreas de la base y la boca deben ser iguales.","Sí, porque el caucho se estira dependiendo del área que encierre, por lo que las relaciones de las áreas y los perímetros son iguales.","No, porque la relación obtenida se cumple para las longitudes de los lados, pero al calcular las áreas, la razón obtenida se eleva al cuadrado.","Sí, porque como las figuras son semejantes, todas sus medidas deben tener la misma razón que los perímetros."],"correct":2,"hint":"Si los lados se multiplican por 3/4, ¿por cuánto se multiplica el área de un cuadrado?","difficulty":"facil","timeLimit":150,"image":"/preguntas/matematicas/portalapices.jpg","explanation":"Base y boca son cuadradas, así que la razón entre sus lados es la de los perímetros, 3/4. El área depende del lado al cuadrado: la razón entre las áreas es (3/4)² = 9/16, no 3/4."},{"id":"mate-08","question":"Un grupo de montañistas sabe que cada vez que aumenta la altitud en 100 m, la temperatura disminuye en 1 °C. Si el grupo se encuentra a una altitud de 1.000 m, donde la temperatura es de 20 °C, ¿cuál de las siguientes expresiones les permite determinar la temperatura que habrá cuando se encuentren a 4.000 m de altitud?","options":["\\(\\text{Temperatura} = -\\dfrac{\\text{Altitud}}{100} + 10 \\)","\\(\\text{Temperatura} = -\\text{Altitud} \\times 100 + 300 \\)","\\(\\text{Temperatura} = -\\dfrac{\\text{Altitud}}{100} + 30 \\)","\\(\\text{Temperatura} = -\\text{Altitud} \\times 100 + 10 \\)"],"correct":2,"hint":"La temperatura BAJA al subir: el término de la altitud debe restar. Prueba cada expresión con 1.000 m.","difficulty":"dificil","timeLimit":90,"explanation":"La temperatura baja 1 °C por cada 100 m: el término es −Altitud/100. Para que a 1.000 m dé 20 °C hay que sumar 30 (−10 + 30 = 20). A 4.000 m: −40 + 30 = −10 °C. B y D multiplican la altitud por 100 en lugar de dividirla."},{"id":"mate-14","question":"Si en un rectángulo se aumenta la longitud de uno de sus lados en 100 %, ¿Qué se puede concluir de su área?","options":["Aumenta en un 50 %.","Se duplica.","No cambia.","Aumenta en 100 unidades."],"correct":1,"hint":"Aumentar un lado en 100 % es multiplicarlo por 2. ¿Qué le pasa a base × altura?","difficulty":"facil","timeLimit":60,"explanation":"Aumentar un lado en 100 % es duplicarlo. Como el área es base × altura y el otro lado no cambia, el área también se duplica."},{"id":"mate-15","question":"Las sombras proyectadas por dos postes paralelos de 10 metros y 5 metros se muestran en la figura.\nEl ángulo entre la acera horizontal y la sombra del poste 1 es α = 30°.\nDe acuerdo con esto, se puede afirmar que el ángulo entre la acera horizontal y la sombra del poste 2 es","options":["β = 5°.","β = 15°.","β = 30°.","β = 60°."],"correct":2,"hint":"Los rayos del sol llegan paralelos a los dos postes.","difficulty":"media","timeLimit":90,"image":"/preguntas/matematicas/sombras-postes.jpg","explanation":"Los postes son paralelos y los ilumina la misma fuente, con rayos paralelos: sus sombras también son paralelas y forman el mismo ángulo con la acera, β = 30°. La altura del poste cambia el largo de la sombra, no su dirección."}]}$mat1$::jsonb;
  v_r2 jsonb := $mat2${"bank":"matematicas","bankRound":2,"passingScore":0,"questions":[{"id":"mate-09","question":"Una persona afirma que para el comerciante es más rentable vender 6 toneladas de mango en la ciudad Z que en la ciudad W.\n¿Por qué la afirmación de esta persona es correcta?","options":["Porque el dinero recibido en la venta del producto en la ciudad Z es mayor que el recibido en la ciudad W.","Porque la diferencia entre el precio de venta por tonelada es mayor que la diferencia entre el costo de transporte por camión.","Porque la diferencia entre las ventas totales en cada ciudad es mayor que la diferencia entre los gastos totales.","Porque el dinero total gastado en empleados y transporte es mayor en la ciudad W que en la ciudad Z."],"correct":2,"hint":"Calcula en cada ciudad lo que se recibe y lo que se gasta: 6 toneladas necesitan 2 camiones y 4 trabajadores.","difficulty":"facil","timeLimit":150,"explanation":"6 toneladas necesitan 2 camiones y 4 trabajadores. En W: ventas 6 × 1.300.000 = 7.800.000 y gastos 2 × 150.000 + 4 × 180.000 = 1.020.000. En Z: ventas 8.100.000 y gastos 2 × 180.000 + 4 × 200.000 = 1.160.000. En Z se vende 300.000 más y se gasta solo 140.000 más: por eso es más rentable. A no basta: también hay que mirar los gastos.","passage":{"intro":"Lee la siguiente información para responder.","title":"Mango y banano para las ciudades W y Z","paragraphs":["Para transportar mango y banano desde un pueblo cercano a dos ciudades, W y Z, un comerciante utiliza tres (3) camiones con capacidad de 5 toneladas cada uno; por cada camión contrata dos trabajadores en cada viaje. El comerciante compra a $ 400.000 la tonelada de banano y a $ 500.000, la de mango. En la tabla se muestra el precio de venta por tonelada de cada producto y los gastos de transporte y de trabajadores para cada ciudad."],"images":[{"url":"/preguntas/matematicas/transporte-frutas.jpg"}]}},{"id":"mate-10","question":"Los tres (3) camiones se cargan con 5 toneladas de banano cada uno para venderse en la ciudad W. El comerciante necesita conocer la ganancia al hacer este negocio, ejecutando el siguiente procedimiento:\nPaso 1. Halla el número de toneladas de banano que hay en los 3 camiones.\nPaso 2. Halla la diferencia entre el precio de venta de una tonelada de banano en la ciudad W y el precio de compra.\nPaso 3. Multiplica los valores hallados en los pasos 1 y 2.\nPaso 4. Encuentra los costos totales de transporte y le suma el pago total de los trabajadores en los tres viajes.\nPaso 5. Halla la diferencia entre el valor obtenido en el paso 3 y el paso 4.\n¿Cuál es la ganancia que obtiene el comerciante?","options":["$ 5.670.000","$ 5.970.000","$ 7.470.000","$ 8.010.000"],"correct":2,"hint":"Sigue los pasos: 15 toneladas, $ 600.000 de diferencia por tonelada… y son 3 camiones con 2 trabajadores cada uno.","difficulty":"facil","timeLimit":150,"explanation":"Paso 1: 15 t. Paso 2: 1.000.000 − 400.000 = 600.000. Paso 3: 15 × 600.000 = 9.000.000. Paso 4: transporte 3 × 150.000 = 450.000 más trabajadores 6 × 180.000 = 1.080.000, en total 1.530.000. Paso 5: 9.000.000 − 1.530.000 = $ 7.470.000.","passage":{"intro":"Lee la siguiente información para responder.","title":"Mango y banano para las ciudades W y Z","paragraphs":["Para transportar mango y banano desde un pueblo cercano a dos ciudades, W y Z, un comerciante utiliza tres (3) camiones con capacidad de 5 toneladas cada uno; por cada camión contrata dos trabajadores en cada viaje. El comerciante compra a $ 400.000 la tonelada de banano y a $ 500.000, la de mango. En la tabla se muestra el precio de venta por tonelada de cada producto y los gastos de transporte y de trabajadores para cada ciudad."],"images":[{"url":"/preguntas/matematicas/transporte-frutas.jpg"}]}},{"id":"mate-11","question":"Para diciembre, el comerciante decidió que por cada 5 toneladas del producto transportado en camión y vendido en alguna de las ciudades, cada uno de los dos empleados necesarios por camión recibirá un bono de 0,3 % del dinero recibido en la venta de esas 5 toneladas. En ese mes, dos empleados transportaron y vendieron 47 toneladas de mango a la ciudad W. Para hallar el bono recibido por cada uno de ellos, se ejecutó el siguiente procedimiento:\nPaso 1. Se dividió el número de toneladas vendidas entre 5 y se halló su residuo.\nPaso 2. Se restó del número de toneladas vendidas, el valor obtenido en el paso 1.\nPaso 3. Se multiplicó el valor obtenido en el paso 2 por el valor de venta de la tonelada del producto.\nPaso 4. Al valor obtenido en el paso 3, se le sacó el 0,3 %.\n¿De que valor fue, aproximadamente, el bono recibido por cada empleado?","options":["526.000 pesos.","175.000 pesos.","148.000 pesos.","87.000 pesos."],"correct":1,"hint":"El bono solo cuenta grupos completos de 5 toneladas: de 47, ¿cuántas entran?","difficulty":"facil","timeLimit":150,"explanation":"47 ÷ 5 deja residuo 2, así que cuentan 45 toneladas. 45 × 1.300.000 = 58.500.000, y el 0,3 % de eso es 175.500: unos 175.000 pesos para cada empleado.","passage":{"intro":"Lee la siguiente información para responder.","title":"Mango y banano para las ciudades W y Z","paragraphs":["Para transportar mango y banano desde un pueblo cercano a dos ciudades, W y Z, un comerciante utiliza tres (3) camiones con capacidad de 5 toneladas cada uno; por cada camión contrata dos trabajadores en cada viaje. El comerciante compra a $ 400.000 la tonelada de banano y a $ 500.000, la de mango. En la tabla se muestra el precio de venta por tonelada de cada producto y los gastos de transporte y de trabajadores para cada ciudad."],"images":[{"url":"/preguntas/matematicas/transporte-frutas.jpg"}]}},{"id":"mate-12","question":"Si se transportan 7 toneladas de fruta a la ciudad W y 10 toneladas de fruta a la ciudad Z, ¿cuál es la gráfica que muestra correctamente la relación de costos por ciudad?","options":["","","",""],"correct":1,"hint":"7 toneladas también necesitan 2 camiones. Calcula transporte y trabajadores en cada ciudad.","difficulty":"facil","timeLimit":120,"optionImages":["/preguntas/matematicas/costos-ciudades-a.jpg","/preguntas/matematicas/costos-ciudades-b.jpg","/preguntas/matematicas/costos-ciudades-c.jpg","/preguntas/matematicas/costos-ciudades-d.jpg"],"explanation":"Tanto 7 como 10 toneladas necesitan 2 camiones y 4 trabajadores. En W: transporte 2 × 150.000 = 300.000 y trabajadores 4 × 180.000 = 720.000. En Z: transporte 2 × 180.000 = 360.000 y trabajadores 4 × 200.000 = 800.000. Es la gráfica B.","passage":{"intro":"Lee la siguiente información para responder.","title":"Mango y banano para las ciudades W y Z","paragraphs":["Para transportar mango y banano desde un pueblo cercano a dos ciudades, W y Z, un comerciante utiliza tres (3) camiones con capacidad de 5 toneladas cada uno; por cada camión contrata dos trabajadores en cada viaje. El comerciante compra a $ 400.000 la tonelada de banano y a $ 500.000, la de mango. En la tabla se muestra el precio de venta por tonelada de cada producto y los gastos de transporte y de trabajadores para cada ciudad."],"images":[{"url":"/preguntas/matematicas/transporte-frutas.jpg"}]}},{"id":"mate-13","question":"Durante enero, el comerciante vendió 100 toneladas de mango y 50 de banano, y contrató 10 trabajadores. ¿Qué se puede determinar con esta información?","options":["La ganancia de los productores.","El pago que recibirá cada trabajador en enero.","Los costos totales del comerciante.","El número mínimo de viajes que se realizaron desde el pueblo."],"correct":3,"hint":"Cada camión lleva máximo 5 toneladas. ¿Qué puedes deducir de 150 toneladas?","difficulty":"dificil","timeLimit":135,"explanation":"Cada camión lleva máximo 5 toneladas: 150 toneladas requieren al menos 150 ÷ 5 = 30 viajes. Lo demás no se puede saber, porque no se conoce a qué ciudad se vendió cada carga ni cuántos viajes hizo cada trabajador.","passage":{"intro":"Lee la siguiente información para responder.","title":"Mango y banano para las ciudades W y Z","paragraphs":["Para transportar mango y banano desde un pueblo cercano a dos ciudades, W y Z, un comerciante utiliza tres (3) camiones con capacidad de 5 toneladas cada uno; por cada camión contrata dos trabajadores en cada viaje. El comerciante compra a $ 400.000 la tonelada de banano y a $ 500.000, la de mango. En la tabla se muestra el precio de venta por tonelada de cada producto y los gastos de transporte y de trabajadores para cada ciudad."],"images":[{"url":"/preguntas/matematicas/transporte-frutas.jpg"}]}},{"id":"mate-16","question":"Una escuela de natación cuenta con un total de 16 estudiantes. Para las clases se usan 2 piscinas con distinta profundidad. Por seguridad, las personas con una estatura inferior a 1,80 m se envían a la piscina menos profunda, y las demás, a la más profunda.\nUn día, el director de la escuela escucha que el promedio de estatura de las 16 personas es 1,70 m e insiste en aumentar la cantidad de alumnos para que el promedio sea 1,80 m, afirmando que de esta manera se logrará igualar la cantidad de personas en las dos piscinas. ¿Por qué es errónea la afirmación del director?","options":["Porque las 16 personas se encuentran actualmente en la piscina menos profunda. El director de la escuela debe aceptar otros 16 alumnos con una estatura superior a 1,80 m.","Porque con el promedio es imposible determinar la cantidad de personas en las piscinas. Es necesario utilizar otras medidas, como la estatura máxima o mínima de las personas, en lugar de esta.","Porque incrementar el promedio a 1,80 m es insuficiente. El director de la escuela debe aceptar más estudiantes con una altura de 1,80 m hasta que la cantidad de alumnos sea igual en ambas piscinas.","Porque aunque el promedio de estatura de las 16 personas sea inferior a 1,80 m, no significa que la cantidad de personas en las piscinas sea diferente."],"correct":3,"hint":"Un promedio no dice cuántas personas están por encima o por debajo de 1,80 m.","difficulty":"media","timeLimit":150,"explanation":"El promedio no informa cómo se reparten las estaturas: con un promedio de 1,70 m puede haber varias personas de más de 1,80 m. Que el promedio sea menor que 1,80 m no implica que las piscinas tengan cantidades distintas, y subirlo a 1,80 m tampoco garantiza que se igualen."},{"id":"mate-17","question":"La longitud de las aristas de la caja de la figura son l, a y h.\n¿Cuál de las siguientes expresiones determina la longitud total de las aristas de la caja?","options":["lah","4lah","l + a + h","4l + 4a + 4h"],"correct":3,"hint":"Cuenta cuántas aristas tiene la caja: ¿cuántas miden l, cuántas a y cuántas h?","difficulty":"dificil","timeLimit":75,"image":"/preguntas/matematicas/caja-aristas.jpg","explanation":"Una caja tiene 12 aristas: 4 de largo l, 4 de ancho a y 4 de alto h. La longitud total es 4l + 4a + 4h. (lah es el volumen.)"},{"id":"mate-18","question":"Un barco navega entre dos faros, ubicados en la parte inferior de la figura.\nEn el instante en que el ángulo formado entre el barco, el faro superior y cualquiera de los otros faros es de 45°, ¿cuál es la distancia x entre el faro superior y el barco?","options":["\\(x = \\dfrac{2\\,\\text{sen}(30^\\circ)}{\\text{sen}(45^\\circ)} \\)","\\(x = \\dfrac{2\\,\\text{sen}(60^\\circ)}{\\text{sen}(45^\\circ)} \\)","\\(x = \\dfrac{\\text{sen}(60^\\circ)}{\\text{sen}(75^\\circ)} \\)","\\(x = \\dfrac{\\text{sen}(30^\\circ)}{\\text{sen}(60^\\circ)} \\)"],"correct":2,"hint":"Usa el triángulo de la derecha: conoces el lado que mide 1 y sus ángulos de 60° y 75°. Ley del seno.","difficulty":"media","timeLimit":105,"image":"/preguntas/matematicas/faros-barco.jpg","explanation":"En el triángulo formado por el faro superior, el faro de la derecha y el barco, el lado que mide 1 está frente al ángulo de 75° (en el barco) y x está frente al de 60°. Por la ley del seno: x / sen(60°) = 1 / sen(75°), así que x = sen(60°) / sen(75°)."},{"id":"mate-19","question":"En una feria robótica, el robot P y el robot Q disputan un juego de tenis de mesa. En el momento que el marcador se encuentra 7 a 2 a favor del robot P, estos se reprograman de tal forma que por cada 2 puntos que anota el robot P, el robot Q anota 3. ¿Cuál de las siguientes ecuaciones permite determinar cuándo igualará en puntos el robot Q al robot P?","options":["\\(\\tfrac{3}{2}x = 0 \\), donde x es la cantidad de puntos que anotará P.","\\(7 + x = \\tfrac{3}{2}x + 2 \\), donde x es la cantidad de puntos que anotará P.","\\(7 + 3x = 2 + 2y \\), donde x es la cantidad de puntos que anotará P, y y la cantidad de puntos que anotará Q.","\\(x + y = 7 + 2 \\), donde x es la cantidad de puntos que anotará P, y y la cantidad de puntos que anotará Q."],"correct":1,"hint":"Si P anota x puntos más, Q anota (3/2)x. Escribe el marcador de cada robot e iguálalos.","difficulty":"dificil","timeLimit":105,"explanation":"Si P anota x puntos, Q anota 3/2 de x (3 por cada 2). P tendrá 7 + x y Q tendrá 2 + (3/2)x. Se igualan cuando 7 + x = (3/2)x + 2: con x = 10 quedan 17 a 17."},{"id":"mate-20","question":"La tabla presenta la información sobre el gasto en publicidad y las ganancias de una empresa durante los años 2020 a 2022.\n¿Cuál es la función que representa la ganancia obtenida G, en millones de pesos, en función del gasto en publicidad p?","options":["G(p) = 30p + 2.000","G(p) = 10p","G(p) = 40p","G(p) = 40p – 800"],"correct":0,"hint":"Prueba cada función con los tres años de la tabla: la correcta debe cumplirse en todos.","difficulty":"facil","timeLimit":90,"image":"/preguntas/matematicas/publicidad-ganancias.jpg","explanation":"G(p) = 30p + 2.000 cumple los tres años: 30 × 200 + 2.000 = 8.000; 30 × 280 + 2.000 = 10.400; 30 × 250 + 2.000 = 9.500. G(p) = 40p solo cumple el primero y G(p) = 40p − 800, ninguno."}]}$mat2$::jsonb;
  c record; m record; v_ronda int; v_new jsonb; v_nombre text;
  v_total int; v_viejas int; v_nuevas int;
begin
  if v_base is null then
    insert into _0080_estado values ('CURSO NO ENCONTRADO', '—', 'No existe el curso de Matemáticas en esta base de datos.');
    return;
  end if;

  for c in
    with recursive fam as (
      select id from public.courses where id = v_base
      union
      select ch.id from public.courses ch join fam on ch.parent_course_id = fam.id
    )
    select co.id, co.name, co.draft_modules is not null as has_draft
      from public.courses co join fam on fam.id = co.id
     order by co.parent_course_id nulls first, co.name
  loop
    -- El borrador guarda los módulos con las preguntas VIEJAS: publicarlo
    -- deshace esta migración en ese curso.
    if c.has_draft then
      insert into _0080_estado values ('BORRADOR PENDIENTE', c.name,
        'Tiene un borrador sin publicar en el editor de ruta: descartarlo antes de publicar, o volverán las preguntas anteriores.');
    end if;
    foreach v_ronda in array array[4, 6] loop
      v_new := case when v_ronda = 4 then v_r1 else v_r2 end;
      v_nombre := case when v_ronda = 4 then 'primera ronda' else 'ronda final' end;
      select * into m from public.course_modules where course_id = c.id and "order" = v_ronda;
      if m.id is null then
        insert into _0080_estado values ('SIN MÓDULO ' || v_ronda, c.name, 'La ruta no tiene módulo en esa posición.');
        continue;
      end if;
      if not (m.type = 'challenge' and m.challenge_data->>'bank' = 'matematicas') then
        insert into _0080_estado values ('NO ES RONDA', c.name,
          format('%s (%s): no es una ronda del banco (%s). No se cambió.', m.title, v_nombre, m.type));
        continue;
      end if;
      select count(*),
             count(*) filter (where e->>'id' ~ '^mat-[0-9]{2}$'),
             count(*) filter (where e->>'id' like 'mate-%')
        into v_total, v_viejas, v_nuevas
        from jsonb_array_elements(coalesce(m.challenge_data->'questions', '[]'::jsonb)) as t(e);
      if v_total > 0 and v_nuevas = v_total then
        insert into _0080_estado values ('YA APLICADA', c.name, m.title || ' (' || v_nombre || ')');
      elsif v_viejas = v_total then
        update public.course_modules
           set challenge_data = jsonb_set(m.challenge_data, '{questions}', v_new->'questions'),
               updated_at = now()
         where id = m.id;
        insert into _0080_estado values ('REEMPLAZADA', c.name,
          format('%s (%s): %s preguntas del banco anterior → %s del nuevo.', m.title, v_nombre, v_total, jsonb_array_length(v_new->'questions')));
      else
        insert into _0080_estado values ('NO TOCADO', c.name,
          format('%s (%s): tiene %s preguntas propias del tutor y %s del banco anterior. Cámbialas desde el editor de ruta ("Elegir del banco").',
                 m.title, v_nombre, v_total - v_viejas - v_nuevas, v_viejas));
      end if;
    end loop;
  end loop;
end $$;

select estado, curso, detalle from _0080_estado order by estado, curso;
